async function api(action,data,form){var options={credentials:'same-origin',headers:{'X-CSRF-Token':csrf}};if(data||form){options.method='POST';if(form)options.body=form;else{options.headers['Content-Type']='application/json';options.body=JSON.stringify(data)}}var r=await fetch('api.php?action='+action,options),j;try{j=await r.json()}catch(e){throw Error('El servidor no devolvió una respuesta válida. Revisa los límites de PHP.')}if(!r.ok)throw Error(j.error||'No se pudo completar la solicitud');return j}
