function save(){if(uploadsPending){alert('Espera a que terminen de subir los archivos y vuelve a pulsar Guardar.');return Promise.reject(Error('Subida en curso'))}var snapshot=JSON.parse(JSON.stringify(D));delete snapshot.leads;var pending=saveQueue.then(async function(){var j=await api('save',{data:snapshot,revision:revision});revision=j.revision;delete D.cfg.pass;applyBrand();return j});saveQueue=pending.catch(function(e){alert('No se guardó: '+e.message)});return pending}
