function view(t){T=t;document.querySelectorAll('aside [data-t]').forEach(function(b){b.classList.toggle('on',b.dataset.t===t)});$('lc').textContent=D.leads.length;var m=$('m');
if(t==='home'){var L=D.leads.slice(-5).reverse();m.innerHTML='<h1>Resumen</h1><p class="sub">Así va tu sitio.</p><div class="kp"><div class="card"><b>'+D.portfolio.length+'</b><span>Proyectos</span></div><div class="card"><b>'+D.news.length+'</b><span>Noticias</span></div><div class="card"><b>'+D.products.length+'</b><span>Productos</span></div><div class="card"><b>'+D.leads.length+'</b><span>Contactos recibidos</span></div></div><div class="card"><div class="bar"><b>Últimos contactos</b><button class="b" onclick="view(\'leads\')">Ver todos</button></div>'+(L.length?'<div class="sc"><table><tr><th>Empresa</th><th>Teléfono</th><th>Origen</th></tr>'+L.map(function(l){return '<tr><td>'+esc(l.empresa)+'</td><td>'+esc(l.tel)+'</td><td>'+esc(l.src)+'</td></tr>'}).join('')+'</table></div>':'<span style="color:var(--mut)">Aún no hay contactos.</span>')+'</div><div class="note">Los cambios se guardan en MySQL y se publican para todos los visitantes. Los archivos se guardan en uploads. Respalda tanto la base de datos como uploads desde cPanel. El JSON exporta contenido y contactos, pero no incluye archivos ni contraseña; al importarlo se conserva la lista actual de contactos.</div>'}
else if(S[t]){var s=S[t];m.innerHTML='<div class="bar"><div><h1>'+s.t+'</h1><p class="sub" style="margin:0">'+s.s+'</p></div><button class="b p" onclick="ed(\''+t+'\')">+ Agregar</button></div><div class="card sc"><table><tr>'+s.c.map(function(k){return '<th>'+lb(s,k)+'</th>'}).join('')+'<th></th></tr>'+D[t].map(function(r,i){return '<tr>'+s.c.map(function(k){var v=r[k];return '<td>'+(typeof v==='boolean'?(v?'✔':'—'):esc(v))+'</td>'}).join('')+'<td style="white-space:nowrap;text-align:right"><button class="b" onclick="mv(\''+t+'\','+i+',-1)">▲</button> <button class="b" onclick="mv(\''+t+'\','+i+',1)">▼</button> <button class="b" onclick="ed(\''+t+'\','+r.id+')">Editar</button> <button class="b d" onclick="rm(\''+t+'\','+r.id+')">Eliminar</button></td></tr>'}).join('')+'</table></div>'}
else if(t==='land'){var H=Object.assign({},HH,D.home||{});m.innerHTML='<div class="bar"><div><h1>Inicio (landing)</h1><p class="sub" style="margin:0">Textos, colores, logo e icono de pestaña. Después de subir una imagen, pulsa Guardar cambios para publicarla.</p></div><button class="b p" id="lsv">Guardar cambios</button></div><form id="lf">'+SCH.map(function(g){return '<div class="card"><b style="font-size:16px">'+g[0]+'</b><div class="g2" style="margin-top:12px">'+g[1].map(function(f){var w=(f[2]&&(f[2]==='textarea'||f[2].indexOf('media')===0))||f[0]==='pill'||f[0]==='foot'?'grid-column:1/-1':'';return '<div style="'+w+'">'+fld(f,H[f[0]])+'</div>'}).join('')+'</div></div>'}).join('')+'<button type="button" class="b d" id="lrs">Restaurar textos originales</button></form>';wm($('lf'));
$('lf').onsubmit=function(e){e.preventDefault();$('lsv').click()};$('lsv').onclick=function(){var f=$('lf').elements,o={};SCH.forEach(function(g){g[1].forEach(function(x){o[x[0]]=f[x[0]].value})});D.home=o;save().then(function(){alert('Landing guardada')})};$('lrs').onclick=function(){if(confirm('¿Restaurar todos los textos originales?')){D.home={};save().then(function(){view('land')})}}}
else if(t==='reel'){var R=Object.assign({title:'Historias con calidad de cine',text:'Mira nuestro trabajo en acción.',poster:'',video:''},D.reel||{});m.innerHTML='<h1>Showreel</h1><p class="sub">Video principal que aparece en el inicio del sitio.</p><form id="rf" class="card" style="display:grid;gap:14px">'+fld(['title','Título'],R.title)+fld(['text','Texto'],R.text)+fld(['poster','Imagen de fondo','media:image'],R.poster)+fld(['video','Video (subir archivo o enlace YouTube/Vimeo)','media:video'],R.video)+'<div><button class="b p">Guardar showreel</button></div></form>';wm($('rf'));$('rf').onsubmit=function(e){e.preventDefault();var f=e.target.elements;D.reel={title:f.title.value,text:f.text.value,poster:f.poster.value,video:f.video.value};save().then(function(){alert('Showreel guardado')})}}
else if(t==='leads'){m.innerHTML='<div class="bar"><div><h1>Contactos</h1><p class="sub" style="margin:0">Empresas y números que dejaron los visitantes.</p></div><button class="b p" onclick="csv()">Descargar CSV</button></div><div class="card sc">'+(D.leads.length?'<table><tr><th>Empresa</th><th>Teléfono</th><th>Origen</th><th>Fecha</th><th></th></tr>'+D.leads.slice().reverse().map(function(l){return '<tr><td>'+esc(l.empresa)+'</td><td>'+esc(l.tel)+'</td><td><span class="tg">'+esc(l.src)+'</span></td><td>'+new Date(l.date).toLocaleString('es')+'</td><td style="white-space:nowrap;text-align:right"><a class="b" target="_blank" rel="noopener" href="https://wa.me/'+String(l.tel).replace(/\D/g,'')+'">WhatsApp</a> <button class="b d" onclick="rl('+l.id+')">Eliminar</button></td></tr>'}).join('')+'</table>':'<span style="color:var(--mut)">Aún no hay contactos.</span>')+'</div>'}
else{m.innerHTML='<h1>Ajustes</h1><p class="sub">Datos generales y respaldo.</p><div class="card" style="display:grid;gap:12px"><label>Correo de contacto<input id="c1" value="'+esc(D.cfg.email)+'"></label><label>Número de WhatsApp (con código de país, solo números. Ej: 50688880000)<input id="c2" inputmode="numeric" placeholder="50688880000" value="'+esc(D.cfg.whatsapp)+'"></label><label>Destino del botón Hola, Fisital (sitio web o wa.me; vacío usa WhatsApp)<input id="c7" placeholder="wa.me/50688880000" value="'+esc(D.cfg.contactUrl||'')+'"></label><label>Mensaje inicial del chat<input id="c6" value="'+esc(D.cfg.waMsg||'Hola Fisital, me gustaría más información.')+'"></label><label>Categorías del portafolio (separadas por coma)<input id="c3" value="'+esc(D.cfg.cats.join(', '))+'"></label><label>Categorías de noticias (separadas por coma)<input id="c4" value="'+esc(D.cfg.ncats.join(', '))+'"></label><label>Nueva contraseña (mínimo 12 caracteres; vacío = no cambiar)<input id="c5" type="password"></label><div><button class="b p" onclick="sc()">Guardar ajustes</button></div></div><div class="card"><b>Respaldo</b><p class="sub" style="margin:4px 0 12px">Exporta todo para guardarlo o moverlo a otro equipo.</p><button class="b" onclick="ex()">Exportar JSON</button> <label class="b" style="display:inline-block">Importar JSON<input type="file" accept=".json" hidden onchange="im(this)"></label> <button class="b d" onclick="rs()">Restablecer datos de ejemplo</button></div>'}}
function lb(s,k){var f=s.f.filter(function(x){return x[0]===k})[0];return f?f[1].replace(/ \(.*/,''):k}
function fld(f,v){var n=f[0],l=f[1],ty=f[2]||'text';if(v==null)v='';
if(ty==='textarea')return '<label>'+l+'<textarea name="'+n+'" rows="3">'+esc(v)+'</textarea></label>';
if(ty==='check')return '<label class="ck"><input type="checkbox" name="'+n+'"'+(v?' checked':'')+'> '+l+'</label>';
if(ty.indexOf('media:')===0)return mf(n,l,ty.slice(6),v);if(ty.indexOf('sel:')===0){var o=ty==='sel:cats'?D.cfg.cats:ty==='sel:ncats'?D.cfg.ncats:ty.slice(4).split('|');return '<label>'+l+'<select name="'+n+'">'+o.map(function(x){return '<option'+(x===v?' selected':'')+'>'+esc(x)+'</option>'}).join('')+'</select></label>'}
return '<label>'+l+'<input type="'+ty+'" name="'+n+'" value="'+esc(v)+'"></label>'}
function ed(t,id){var s=S[t],r=id?D[t].filter(function(x){return x.id===id})[0]:Object.assign({},s.n),f=$('df');f.innerHTML='<b style="font-size:18px">'+(id?'Editar':'Agregar')+' · '+s.t+'</b>'+s.f.map(function(x){return fld(x,r[x[0]])}).join('')+'<div style="display:flex;gap:8px;justify-content:flex-end"><button type="button" class="b" onclick="$(\'dg\').close()">Cancelar</button><button class="b p">Guardar</button></div>';
wm(f);f.onsubmit=function(e){e.preventDefault();s.f.forEach(function(x){var el=f.elements[x[0]];r[x[0]]=x[2]==='check'?el.checked:el.value});if(t==='news'&&r.feat){D.news.forEach(function(n){n.feat=false;});r.feat=true;}if(!id){r.id=Date.now();D[t].push(r)}save().then(function(){$('dg').close();view(t)})};$('dg').showModal()}
function rm(t,id){if(confirm('¿Eliminar este elemento?')){D[t]=D[t].filter(function(x){return x.id!==id});save().then(function(){view(t)})}}
function mv(t,i,d){var j=i+d,a=D[t];if(j<0||j>=a.length)return;var x=a[i];a[i]=a[j];a[j]=x;save().then(function(){view(t)})}
function rl(id){if(confirm('¿Eliminar contacto?'))api('delete_lead',{id:id}).then(function(){D.leads=D.leads.filter(function(x){return x.id!==id});view('leads')}).catch(function(e){alert(e.message)})}
function dl(n,c,m){var a=document.createElement('a');a.href=URL.createObjectURL(new Blob([c],{type:m}));a.download=n;a.click()}
function csv(){var q=function(v){return '"'+String(v).replace(/^[=+@\t\r-]/,function(x){return "'"+x}).replace(/"/g,'""')+'"'};dl('contactos-fisital.csv','\ufeffEmpresa,Teléfono,Origen,Fecha\n'+D.leads.map(function(l){return [l.empresa,l.tel,l.src,l.date].map(q).join(',')}).join('\n'),'text/csv')}
function ex(){var copy=JSON.parse(JSON.stringify(D));delete copy.cfg.pass;dl('fisital-datos.json',JSON.stringify(copy,null,2),'application/json')}
function im(i){var file=i.files[0];if(!file)return;if(file.size>1500000){alert('Respaldo demasiado grande');return}var r=new FileReader();r.onload=function(){try{var d=JSON.parse(r.result);if(!d.portfolio||!d.news||!d.products)throw Error();d.leads=D.leads;d.clients=Array.isArray(d.clients)?d.clients:(D.clients||[]);D=d;save().then(function(){view('cfg');alert('Contenido importado. Los contactos existentes se conservaron.')})}catch(e){alert('Archivo no válido')}};r.readAsText(file)}
function rs(){if(confirm('¿Restaurar el contenido de ejemplo? Los contactos y la contraseña se conservarán.')){var leads=D.leads;D=JSON.parse(JSON.stringify(DEF));D.leads=leads;save().then(function(){view('cfg')})}}
function sc(){var l=function(v){return v.split(',').map(function(x){return x.trim()}).filter(Boolean)};D.cfg.email=$('c1').value;D.cfg.whatsapp=$('c2').value.replace(/\D/g,'');D.cfg.waMsg=$('c6').value;D.cfg.contactUrl=FisitalLinks.normalize($('c7').value);D.cfg.cats=l($('c3').value);D.cfg.ncats=l($('c4').value);if($('c5').value)D.cfg.pass=$('c5').value;save().then(function(){alert('Ajustes guardados')})}
</script></body></html>